// RESPONSIBILITY: Defines runtime validation schemas for usage_analytics; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_usage/usage_analytics/schemas/AdminBillingUsageAnalyticsSchemas.ts)

import { isValid, parseISO, format } from 'date-fns';
// Generated by ts-to-zod
import { z } from "zod";

export const statusSchema = z.union([z.literal("idle"), z.literal("loading"), z.literal("success"), z.literal("error")]);

const adminUsageDateSchema = z.string().refine((value) => /^\d{4}-\d{2}-\d{2}$/.test(value) && isValid(parseISO(value)) && format(parseISO(value), 'yyyy-MM-dd') === value, 'usage.validation.invalidDate');
const adminUsageBillingCycleEndSchema = z.string().refine((value) => {
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return adminUsageDateSchema.safeParse(value).success;
    const parsed = parseISO(value);
    return value.includes('T') && isValid(parsed) && !Number.isNaN(Date.parse(value));
}, 'usage.validation.invalidDate');

export const adminUsageHistoryPointSchema = z.object({
    date: adminUsageDateSchema,
    membersUsed: z.number().int().nonnegative(),
    storageUsedGb: z.number().nonnegative(),
    smsUsed: z.number().int().nonnegative()
});

export const adminUsageDataSchema = z.object({
    tenantId: z.string(),
    planName: z.string(),
    planTier: z.union([z.literal("Starter"), z.literal("Growth"), z.literal("Pro"), z.literal("Enterprise")]),
    billingCycleEnd: adminUsageBillingCycleEndSchema,
    monthlyPrice: z.number().int().nonnegative(),
    smsSent: z.number().int().nonnegative(),
    smsLimit: z.number().int().nonnegative(),
    databaseGb: z.number().nonnegative(),
    mediaGb: z.number().nonnegative(),
    storageLimitGb: z.number().nonnegative(),
    activeMembers: z.number().int().nonnegative(),
    memberLimit: z.number().int().nonnegative(),
    staffCount: z.number().int().nonnegative(),
    staffLimit: z.number().int().nonnegative(),
    branchCount: z.number().int().nonnegative(),
    branchLimit: z.number().int().nonnegative(),
    apiCallsToday: z.number().int().nonnegative(),
    apiCallsLimit: z.number().int().nonnegative(),
    usageHistory: z.array(adminUsageHistoryPointSchema)
});

export const adminUsageMetricSchema = z.object({
    label: z.string(),
    used: z.number().nonnegative(),
    limit: z.number().nonnegative(),
    unit: z.string(),
    warningThreshold: z.number().min(0).max(1),
    criticalThreshold: z.number().min(0).max(1)
});
